import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Determine watermark high_ts
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]
    else:
        high_ts = None

    # Filter events already applied (event_ts <= high_ts) -> keep only > high_ts
    events = cdc_events.copy()
    if high_ts is not None:
        events = events[events["event_ts"] > high_ts]
    else:
        events = events.copy()

    # Sort events by (event_ts, event_seq) ascending for sequential application
    events = events.sort_values(by=["event_ts", "event_seq"], kind="mergesort")

    # Initialize state from target_snapshot
    state = {}
    for _, row in target_snapshot.iterrows():
        item_id = row["item_id"]
        state[item_id] = {
            "qty": row["qty_on_hand"],
            "last_ts": row["last_event_ts"],
            "present": True,
        }

    # Apply events sequentially
    for _, ev in events.iterrows():
        item_id = ev["item_id"]
        op = ev["op"]
        qty = ev["qty"]
        ts = ev["event_ts"]

        if item_id not in state:
            state[item_id] = {"qty": 0, "last_ts": None, "present": False}

        s = state[item_id]

        if op == "R":
            if not s["present"]:
                s["qty"] = 0
            s["qty"] = s["qty"] + qty
            s["present"] = True
        elif op == "A":
            s["qty"] = qty
            s["present"] = True
        elif op == "D":
            s["present"] = False

        s["last_ts"] = ts

    # Build output snapshot from present items
    out_rows = []
    for item_id, s in state.items():
        if s["present"]:
            out_rows.append(
                {
                    "item_id": item_id,
                    "qty_on_hand": s["qty"],
                    "last_event_ts": s["last_ts"],
                }
            )

    new_snapshot = pd.DataFrame(out_rows, columns=["item_id", "qty_on_hand", "last_event_ts"])

    return {"new_snapshot": new_snapshot}
